item.content:encoded:
/* Hyperlinks */

a:hover,
a:active,
a:focus,
.et_pb_blog_0_tb_body .et_pb_post .entry-title a:hover,
.et_pb_blog_0_tb_body .et_pb_post .entry-title a:active,
.et_pb_blog_0_tb_body .et_pb_post .entry-title a:focus {
	color: #1a0dab !important;
}

#site-footer a:hover,
#site-footer a:active,
#site-footer a:focus {
	color: #5cd8ad !important;
}

/* Site Logo */

#md-logo h1 {
	margin: 0 !important;
	padding: 0 !important;
	line-height: 1 !important;
}
#md-logo a,
#md-logo a:link {
	color: #1a0dab !important;
	line-height: 70px !important;
}
#md-logo a:hover,
#md-logo a:active,
#md-logo a:focus {
	color: #d30055 !important;
	line-height: 70px !important;
}

/* Accessible hiding */
.acc-hide {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.acc-hide:focus {
  clip: auto;
  height: auto;
  margin: 0;
  overflow: visible;
  position: static;
  white-space: normal;
  width: auto;
}


/* Buttons */

body input[type=submit]:hover,
body input[type=submit]:active,
body input[type=submit]:focus {
	color: #fff !important;
	background-color: #7f0033 !important;
}
body #page-container .et_pb_section .et_pb_button_0_tb_footer {
	color: #fff !important;
	background-color: #d30055 !important;
	border-color: #d30055 !important;
}
body #page-container .et_pb_section .et_pb_button_0_tb_footer:hover,
body #page-container .et_pb_section .et_pb_button_0_tb_footer:active,
body #page-container .et_pb_section .et_pb_button_0_tb_footer:focus {
	color: #fff !important;
	background-color: #5cd8ad !important;
	border-color: #5cd8ad !important;
}

/* WordPress Block Image Captions */
figure.wp-block-image {
	line-height: 1.5;
}

/* Primary navigation on Desktop */
.et_pb_menu--without-logo .et_pb_menu__menu>nav>ul>li {
	margin: 0 !important;
	padding: 0 !important;
	line-height: 1;
}
.et_pb_menu--without-logo .et_pb_menu__menu>nav>ul>li.current_page_item {
	font-style: italic;
	font-weight: bold;
}
header .et_pb_menu--without-logo .et_pb_menu__menu>nav>ul>li>a {
	padding: 0 15px !important;
	line-height: 70px;
}

/* Search field */
.et_pb_menu .et_pb_menu__search-input,
.et-db #et-boc .et-l .et_pb_menu .et_pb_menu__search-input {
	padding: .5rem 1rem;
	color: #000;
	background-color: transparent;
	border: 1px solid #1a0dab;
}

/* Center Primary Navigation on Mobile */
@media (max-width: 980px) {
	header .et_pb_menu--style-left_aligned .et_pb_menu__wrap {
    		justify-content: center !important;
	}
	header .et_pb_menu--style-left_aligned .et_pb_menu__wrap .et_pb_menu__icon.et_pb_menu__cart-button {
    		order: 3 !important;
    		line-height: 70px;
	}
	header .et_pb_menu--style-left_aligned .et_pb_menu__wrap .et_pb_menu__icon.et_pb_menu__search-button {
    		order: 2 !important;
    		line-height: 70px;
	}
	header .et_pb_menu--style-left_aligned .et_pb_menu__wrap .et_mobile_nav_menu {
    		order: 1 !important;
    		line-height: 70px;
	}
}

/* Front page */
.md-myname {
	color: #8d99ae;
}
.md-arabic {
	font-size: 1.75rem;
}
.home .pagination {
	padding-top: 1.5rem;
	padding-bottom: 1.5rem;
}

@media (max-width: 980px) {
	#mdv-testimonial > div {
		display: flex !important;
		flex-direction: column;
	}
	#mdv-testimonial .mdv-testimonial-col1 {
	    order: 2;
	}
	#mdv-testimonial .mdv-testimonial-col2 {
	    order: 1;
	}
}
#mdv-testimonial .mdv-testimonial-col1 h3 {
    margin-bottom: 1rem;
}
@media (max-width: 980px) {
	#mdv-portfolio > div {
		display: flex !important;
		flex-direction: column;
	}
	#mdv-portfolio .mdv-portfolio-col2 .et_pb_portfolio_grid_items {
	    display: grid !important;
	    grid-template-columns: 1fr 1fr;
	    grid-template-rows: 1;
	}
	#mdv-portfolio .mdv-portfolio-col2 .et_pb_portfolio_grid_items .project {
	    width: auto;
	}
	#mdv-portfolio .mdv-portfolio-col2 .pagination {
	    padding-right: 3rem;
	    padding-left: 3rem;
	}
}

/* Image Captions in Post Thumbnails */
.pac_dih__image_details {
	position: relative;
	margin: 0;
	margin-top: -29px;
	padding-right: 5px;
	text-align: right;
}
.pac_dih__image_details .pac_dih__caption {
	display: inline-block;
	margin: 0;
	padding: 0 0.3rem;
	background-color: rgba(255, 255, 255, 0.85)
}
.pac_dih__image_details .pac_dih__caption a {
	color: #8d99ae;
}

/* Added to cart notice */

.woocommerce-notices-wrapper .woocommerce-message a.button.wc-forward {
	color: #fff !important;
}

/* Cart and Search Button */

header .et_pb_menu__icon.et_pb_menu__cart-button.et_pb_menu__icon__with_count,
header .et_pb_menu__icon.et_pb_menu__search-button {
	margin: 0 0 0 1.75rem !important
}

/* Product Image in Cart */

.woocommerce-cart table.cart img {
	width: 150px;
}


/* Blurp Project Date in Projects */

.single-project .mdv-project-blurb .et_pb_blurb_description,
.single-project .mdv-project-blurb .et_pb_blurb_container,
.single-project .mdv-project-blurb .et_pb_blurb_content,
.single-project .mdv-project-blurb .et_pb_main_blurb_image,
.single-project .mdv-project-excerpt .et_pb_text_inner {
	display: inline-block !important;
}
.single-project .mdv-project-blurb,
.single-project .mdv-project-excerpt {
	display: table;
	padding: 0 !important;
}
.single-project .mdv-project-blurb .et_pb_blurb_content,
.single-project .mdv-project-excerpt .et_pb_text_inner {
	padding: 8px 16px 0 16px !important;
	line-height: 30px;
	background-color: rgba(255,255,255,.9) !important;
}
.single-project .mdv-project-excerpt .et_pb_text_inner {
	padding: 0 16px 8px 16px !important;
}

.single-project .mdv-project-blurb .et_pb_main_blurb_image,
.single-project .mdv-project-excerpt .et_pb_text_inner {
	margin-bottom: 0;
}

/* Sidebar Widgets */
#sidebar .et_pb_widget {
	margin-bottom: 2rem;
}

.et_pb_widget .wp-block-search__input {
	border-color: #37c6e8;
}

.et_pb_widget .wp-block-search__button {
	color: #fff;
	background-color: #37c6e8;
	border-color: #37c6e8;
}
.et_pb_widget .wp-block-search__button:hover,
.et_pb_widget .wp-block-search__button:active,
.et_pb_widget .wp-block-search__button:focus {
	background-color: #1a0dab;
	border-color: #1a0dab;
}

#sidebar .widgettitle {
	margin-bottom: 2rem;
	padding: 0;
	font-size: 23px;
	line-height: 1.25;
}
#sidebar .product_list_widget li {
	margin-bottom: .5rem;
	padding: 0 .5rem 0 0;
	border-bottom: 1px solid #efefef;
}
#sidebar .product_list_widget .product-title {
	font-size: 13px;
	font-weight: normal;
}
#sidebar .product_list_widget img {
	width: 63px;
	margin-top: 5px;
	margin-left: 0.5rem;
	border-radius: 3px;
}
#sidebar .product_list_widget .woocommerce-Price-amount,
#sidebar .product_list_widget .wc-gzd-additional-info.wc-gzd-additional-info-loop.tax-info {
	display: none;
}

/* Footer */

/*show desktop menu on phone*/

@media (max-width: 980px) {
	footer .et_pb_menu--style-left_aligned .et_pb_menu__wrap {
    		justify-content: flex-start !important;
	}
}

@media only screen and (max-width : 980px) {
	footer .et_pb_menu__menu {
		display: block !important;
	}
	footer .et_mobile_nav_menu {
		display: none !important;
	}
}

footer nav>ul#menu-footer-menu {
	display: block !important;
}
footer nav>ul#menu-footer-menu li {
	display: block !important;
	padding-top: 0 !important;
	line-height: 2 !important;
}

/* Contact Form */

.et-pb-contact-message p {
	color: #fff;
}

/* Hyperlinks */
a {
	outline: none;
}
a:hover,
a:active
.et_pb_blog_0_tb_body .et_pb_post .entry-title a:hover,
.et_pb_blog_0_tb_body .et_pb_post .entry-title a:active {
	color: #1a0dab !important;
}

#site-footer a:hover,
#site-footer a:active {
	color: #5cd8ad !important;
}

/* Site Logo */

#md-logo h1 {
	margin: 0 !important;
	padding: 0 !important;
	line-height: 1 !important;
}
#md-logo a,
#md-logo a:link {
	color: #fff !important;
	line-height: 70px !important;
}
@media (max-width: 980px) {
	#md-logo a,
	#md-logo a:link {
		line-height: 50px !important;
	}	
}
.et_pb_sticky #md-logo a,
.et_pb_sticky #md-logo a:link {
	color: #1a0dab !important;
}
#md-logo a:hover,
#md-logo a:active {
	color: #d30055 !important;
}

/* Accessible hiding */
.acc-hide {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.acc-hide:focus {
  clip: auto;
  height: auto;
  margin: 0;
  overflow: visible;
  position: static;
  white-space: normal;
  width: auto;
}

/* Strike Diagonal */
.strikediag {
  display: inline-block;
  position: relative;
}
.strikediag::before {
  content: '';
  position: absolute;
  left: -0.1em;
  right: -0.1em;
  top: 0.38em;
  bottom: 0.38em;
  background: linear-gradient(to left top, transparent 45.5%, currentColor 47.5%, currentColor 52.5%, transparent 54.5%);
  pointer-events: none;
}

/* Header */

div.et_pb_section.et_pb_section_1_tb_header {
	background-image: none !important;
	background-color: transparent !important;
}
.et_pb_row_1_tb_header.et_pb_row {
	background-color: transparent;
}

/* Buttons */

body input[type=submit]:hover,
body input[type=submit]:active {
	color: #fff !important;
	background-color: #7f0033 !important;
}
body #page-container .et_pb_section .et_pb_button_0_tb_footer {
	color: #fff !important;
	background-color: #d30055 !important;
	border-color: #d30055 !important;
}
body #page-container .et_pb_section .et_pb_button_0_tb_footer:hover,
body #page-container .et_pb_section .et_pb_button_0_tb_footer:active {
	color: #fff !important;
	background-color: #5cd8ad !important;
	border-color: #5cd8ad !important;
}
body.et_pb_button_helper_class .et_pb_button:hover,
body.et_pb_button_helper_class .et_pb_button:active,
body.et_pb_button_helper_class .et_pb_module.et_pb_button:hover,
body.et_pb_button_helper_class .et_pb_module.et_pb_button:active {
	color: #fff !important;
}

/* Buttons next to each other */
.btns-nteo .et_pb_button_module_wrapper {
  display: inline-block;
  margin: 0 1rem 0 0; /* Abstand zwischen den Buttons, nach Bedarf anpassen */
}

.btns-nteo {
  text-align: left !important; /* Buttons zentrieren, alternativ left oder right */
}


/* Contact Success Message */
.et-pb-contact-message p {
	display: inline-block;
	padding: 0.5rem;
	font-size: 2rem;
	line-height: 1.5;
	color: #5cd8ad !important;
	background-color: #0d0755;
	border-radius: 3px;
}

/* WordPress Block Image Captions */
figure.wp-block-image {
	line-height: 1.5;
}

/* Primary navigation on Desktop */
.et_pb_menu--without-logo .et_pb_menu__menu>nav>ul>li {
	margin: 0 !important;
	padding: 0 !important;
	line-height: 1;
}
.et_pb_menu--without-logo .et_pb_menu__menu>nav>ul>li.current_page_item {
	font-style: italic;
