/* Single Blog Posts */

.md-single-post-header .md-blurb-author a {
	color: #5cd8ad;
}
.md-single-post-header .md-blurb-author a:hover,
.md-single-post-header .md-blurb-author a:active {
	color: #f9f685 !important;
}
.md-post-metadata {}
.md-post-content {}

.single-post .md-post-content .et_pb_section {
	padding: 0 !important;
}
.single-post .md-post-content .et_pb_section > .et_pb_row {
	width: 100%;
	padding: 0 !important;
}
.single-post #main-content .et_pb_blurb_content {
